   286→/// Helper: Compute PSNR between rendered and target images
   287→fn compute_psnr(rendered: &[Vector3<f32>], target: &[Vector3<f32>]) -> f32 {
   288→    let mse = l2_loss(rendered, target);
   289→    if mse < 1e-10 {
   290→        return 100.0; // Cap at 100 dB for near-perfect matches
   291→    }
   292→    10.0 * (1.0 / mse).log10()
   293→}
   294→
   295→/// Helper: Compute SSIM between rendered and target images (simplified version)
   296→/// Using a simple luminance-based approximation for now
   297→fn compute_ssim(rendered: &[Vector3<f32>], target: &[Vector3<f32>]) -> f32 {
   298→    // Constants for SSIM (from Wang et al.)
   299→    let c1 = 0.01_f32.powi(2);
   300→    let c2 = 0.03_f32.powi(2);
   301→
   302→    let n = rendered.len() as f32;
   303→
   304→    // Compute means
   305→    let mu_x: f32 = rendered.iter().map(|v| (v.x + v.y + v.z) / 3.0).sum::<f32>() / n;
   306→    let mu_y: f32 = target.iter().map(|v| (v.x + v.y + v.z) / 3.0).sum::<f32>() / n;
   307→
   308→    // Compute variances and covariance
   309→    let mut var_x = 0.0;
   310→    let mut var_y = 0.0;
   311→    let mut cov_xy = 0.0;
   312→
   313→    for (r, t) in rendered.iter().zip(target.iter()) {
   314→        let rx = (r.x + r.y + r.z) / 3.0;
   315→        let ty = (t.x + t.y + t.z) / 3.0;
   316→        var_x += (rx - mu_x).powi(2);
   317→        var_y += (ty - mu_y).powi(2);
   318→        cov_xy += (rx - mu_x) * (ty - mu_y);
   319→    }
   320→    var_x /= n;
   321→    var_y /= n;
   322→    cov_xy /= n;
   323→
   324→    // Compute SSIM
   325→    let numerator = (2.0 * mu_x * mu_y + c1) * (2.0 * cov_xy + c2);
   326→    let denominator = (mu_x.powi(2) + mu_y.powi(2) + c1) * (var_x + var_y + c2);
   327→
   328→    numerator / denominator
   329→}
   330→
   331→/// TC-OPT-011: Multi-Gaussian Scene Fitting
   332→///
   333→/// Pass Criteria:
   334→/// - PSNR > 35 dB
   335→/// - SSIM > 0.95
   336→/// - Loss converged (< 1% change over last 100 iterations)
   337→///
   338→/// This test verifies that the optimizer can fit multiple Gaussians to a simple
   339→/// synthetic scene with 10 non-overlapping Gaussians from 8 views over 1000 iterations.
   340→#[test]
   341→fn tc_opt_011_multi_gaussian_scene_fitting() {
   342→    println!("\n=== TC-OPT-011: Multi-Gaussian Scene Fitting ===\n");
   343→
   344→    // Create 8 cameras at different viewpoints
   345→    let cameras = vec![
   346→        // Camera 1: Front view (looking down +Z)
   347→        Camera::new(
   348→            200.0, 200.0, 64.0, 64.0, 128, 128,
   349→            Matrix3::identity(),
   350→            Vector3::zeros(),
   351→        ),
   352→        // Camera 2: 45° around Y axis
   353→        Camera::new(
   354→            200.0, 200.0, 64.0, 64.0, 128, 128,
   355→            UnitQuaternion::from_axis_angle(&Vector3::y_axis(), 0.785).to_rotation_matrix().into_inner(),
   356→            Vector3::new(2.0, 0.0, 2.0),
   357→        ),
   358→        // Camera 3: 90° around Y axis (side view)
   359→        Camera::new(
   360→            200.0, 200.0, 64.0, 64.0, 128, 128,
   361→            UnitQuaternion::from_axis_angle(&Vector3::y_axis(), 1.57).to_rotation_matrix().into_inner(),
   362→            Vector3::new(4.0, 0.0, 0.0),
   363→        ),
   364→        // Camera 4: 135° around Y axis
   365→        Camera::new(
   366→            200.0, 200.0, 64.0, 64.0, 128, 128,
   367→            UnitQuaternion::from_axis_angle(&Vector3::y_axis(), 2.356).to_rotation_matrix().into_inner(),
   368→            Vector3::new(2.0, 0.0, -2.0),
   369→        ),
   370→        // Camera 5: View from above (looking down -Y)
   371→        Camera::new(
   372→            200.0, 200.0, 64.0, 64.0, 128, 128,
   373→            UnitQuaternion::from_axis_angle(&Vector3::x_axis(), 1.57).to_rotation_matrix().into_inner(),
   374→            Vector3::new(0.0, 4.0, 0.0),
   375→        ),
   376→        // Camera 6: View from below (looking up +Y)
   377→        Camera::new(
   378→            200.0, 200.0, 64.0, 64.0, 128, 128,
   379→            UnitQuaternion::from_axis_angle(&Vector3::x_axis(), -1.57).to_rotation_matrix().into_inner(),
   380→            Vector3::new(0.0, -4.0, 0.0),
   381→        ),
   382→        // Camera 7: Diagonal view (30° elevation)
   383→        Camera::new(
   384→            200.0, 200.0, 64.0, 64.0, 128, 128,
   385→            UnitQuaternion::from_axis_angle(&Vector3::x_axis(), 0.52)
   386→                .to_rotation_matrix()
   387→                .matrix()
   388→                * UnitQuaternion::from_axis_angle(&Vector3::y_axis(), 0.785)
   389→                    .to_rotation_matrix()
   390→                    .matrix(),
   391→            Vector3::new(2.0, 2.0, 2.0),
   392→        ),
   393→        // Camera 8: Another diagonal view (-30° elevation)
   394→        Camera::new(
   395→            200.0, 200.0, 64.0, 64.0, 128, 128,
   396→            UnitQuaternion::from_axis_angle(&Vector3::x_axis(), -0.52)
   397→                .to_rotation_matrix()
   398→                .matrix()
   399→                * UnitQuaternion::from_axis_angle(&Vector3::y_axis(), -0.785)
   400→                    .to_rotation_matrix()
   401→                    .matrix(),
   402→            Vector3::new(-2.0, -2.0, 2.0),
   403→        ),
   404→    ];
   405→
   406→    // Create 10 non-overlapping target Gaussians in a grid-like pattern
   407→    let mut target_gaussians = Vec::new();
   408→    let colors = vec![
   409→        Vector3::new(1.0, 0.0, 0.0),  // Red
   410→        Vector3::new(0.0, 1.0, 0.0),  // Green
   411→        Vector3::new(0.0, 0.0, 1.0),  // Blue
   412→        Vector3::new(1.0, 1.0, 0.0),  // Yellow
   413→        Vector3::new(1.0, 0.0, 1.0),  // Magenta
   414→        Vector3::new(0.0, 1.0, 1.0),  // Cyan
   415→        Vector3::new(1.0, 0.5, 0.0),  // Orange
   416→        Vector3::new(0.5, 0.0, 1.0),  // Purple
   417→        Vector3::new(0.0, 1.0, 0.5),  // Teal
   418→        Vector3::new(1.0, 0.5, 0.5),  // Pink
   419→    ];
   420→
   421→    // Position Gaussians in a 2x5 grid pattern at Z=8
   422→    for i in 0..10 {
   423→        let row = i / 5;
   424→        let col = i % 5;
   425→        let x = (col as f32 - 2.0) * 1.5; // Spread out in X
   426→        let y = (row as f32 - 0.5) * 1.5; // Spread out in Y
   427→
   428→        target_gaussians.push(Gaussian::new(
   429→            Vector3::new(x, y, 8.0),
   430→            Vector3::new(-1.5, -1.5, -1.5),  // Small uniform scale
   431→            UnitQuaternion::identity(),
   432→            1.0,  // Higher opacity for visibility
   433→            sh_constant_color(colors[i]),
   434→        ));
   435→    }
   436→
   437→    // Render target images from all 8 views
   438→    let background = Vector3::zeros();
   439→    let target_images: Vec<Vec<Vector3<f32>>> = cameras
   440→        .iter()
   441→        .map(|cam| render_full_linear(&target_gaussians, cam, &background, false))
   442→        .collect();
   443→
   444→    // Initialize fitted Gaussians with different parameters (random initialization)
   445→    let mut fitted_gaussians: Vec<Gaussian> = (0..10)
   446→        .map(|i| {
   447→            let row = i / 5;
   448→            let col = i % 5;
   449→            let x = (col as f32 - 2.0) * 1.5;
   450→            let y = (row as f32 - 0.5) * 1.5;
   451→
   452→            Gaussian::new(
   453→                Vector3::new(x, y, 8.0),  // Keep positions fixed
   454→                Vector3::new(-2.0, -2.0, -2.0),  // Different scale
   455→                UnitQuaternion::identity(),
   456→                1.0,  // Same opacity
   457→                sh_constant_color(Vector3::new(0.5, 0.5, 0.5)),  // Gray initial color
   458→            )
   459→        })
   460→        .collect();
   461→
   462→    // Training hyperparameters
   463→    // Start with moderate LR and use gentle decay to enable convergence
   464→    let lr_scale_initial = 1.0;
   465→    let lr_color_initial = 8.0;
   466→    let iters = 1500;
   467→
   468→    println!("Initial state: 10 Gaussians, 8 views, {} iterations", iters);
   469→    println!();
   470→
   471→    let mut prev_losses = Vec::new();
   472→
   473→    // Optimization loop
   474→    for iter in 0..iters {
   475→        // Accumulate gradients across all views
   476→        let mut total_d_colors = vec![Vector3::zeros(); 10];
   477→        let mut total_d_scales = vec![Vector3::zeros(); 10];
   478→        let mut total_loss = 0.0;
