        ];

        let loss = l2_loss(&img_a, &img_b);

        // Reference calculation:
        // Pixel 0: ||[-0.3, -0.3, -0.3]||² = 0.09 + 0.09 + 0.09 = 0.27
        // Pixel 1: ||[0.3, 0.3, 0.3]||² = 0.09 + 0.09 + 0.09 = 0.27
        // Mean: (0.27 + 0.27) / 2 = 0.27
        let expected = 0.27_f32;

        println!("  Our L2 loss: {:.10}", loss);
