        ),
    ];

    // Create 10 non-overlapping target Gaussians in a grid-like pattern
    let mut target_gaussians = Vec::new();
    let colors = vec![
        Vector3::new(1.0, 0.0, 0.0),  // Red
        Vector3::new(0.0, 1.0, 0.0),  // Green
        Vector3::new(0.0, 0.0, 1.0),  // Blue
